using FluentAssertions;
using System;
using System.Collections.Generic;
using Xunit;

namespace Marimo.Parser.Test;

public class JSONArrayのテスト
{
    [Fact]
    public void 空の要素列から空の配列を作ります()
    {
        new JSONArray([]).Elements.Should().BeEmpty();
    }

    [Fact]
    public void 要素列がnullでも空の配列を作ります()
    {
        new JSONArray(null!).Elements.Should().BeEmpty();
    }

    [Fact]
    public void 要素の順序と参照を保持し元の配列とは独立して変更できます()
    {
        var first = new JSONLiteral("first", LiteralType.String);
        var second = new JSONLiteral("second", LiteralType.String);
        var replacement = new JSONLiteral("replacement", LiteralType.String);
        IJSONValue[] elements = [first, second];

        var tested = new JSONArray(elements);
        elements[0] = replacement;

        tested.Elements.Should().Equal(first, second);

        tested.Elements[1] = first;
        elements.Should().Equal(replacement, second);
    }

    [Fact]
    public void 要素列は構築時に一度だけ列挙して解放します()
    {
        var first = new JSONLiteral("first", LiteralType.String);
        var second = new JSONLiteral("second", LiteralType.String);
        var enumerationCount = 0;
        var disposalCount = 0;

        IEnumerable<IJSONValue> Enumerate()
        {
            enumerationCount++;
            try
            {
                yield return first;
                yield return second;
            }
            finally
            {
                disposalCount++;
            }
        }

        var tested = new JSONArray(Enumerate());

        tested.Elements.Should().Equal(first, second);
        enumerationCount.Should().Be(1);
        disposalCount.Should().Be(1);
    }

    [Fact]
    public void 列挙中の例外をそのまま伝播して列挙子を解放します()
    {
        var exception = new InvalidOperationException("enumeration failed");
        var disposalCount = 0;

        IEnumerable<IJSONValue> Enumerate()
        {
            try
            {
                yield return new JSONLiteral("first", LiteralType.String);
                throw exception;
            }
            finally
            {
                disposalCount++;
            }
        }

        var construct = () => new JSONArray(Enumerate());

        construct.Should().Throw<InvalidOperationException>().Which.Should().BeSameAs(exception);
        disposalCount.Should().Be(1);
    }
}

