function Get-Hash([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash }
function Get-RelativePath([string]$Path) { [IO.Path]::GetRelativePath($repo, $Path).Replace('\', '/') }
function Read-Json([string]$Path) { Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -DateKind String }

if (Test-Path -LiteralPath $output) {
    $existing = Read-Json $output
    $summaryPath = Join-Path $root 'exploration-summary.json'
    $summary = Read-Json $summaryPath
    if ($summary.Experiment -ne '2026-10-19-json-array-bulk' -or $summary.PairCount -ne 8 -or $summary.DegreesOfFreedom -ne 7) { throw 'Updated exploration summary identity/design mismatch.' }
    if ([math]::Abs($summary.PairedGeometricMeanRatio - $existing.FormalExploration.Summary.PairedGeometricMeanRatio) -gt 1e-12 -or [math]::Abs($summary.Confidence95.Upper - $existing.FormalExploration.Summary.Confidence95.Upper) -gt 1e-12) { throw 'Updated summary changed a measured result.' }
    $existing.FormalExploration.Summary = $summary
    $existing.FormalExploration.SummarySHA256 = Get-Hash $summaryPath
    foreach ($name in 'Summarize.ps1','Build-Evidence.ps1') {
        $scriptPath = Join-Path $root "scripts/$name"
        $relative = Get-RelativePath $scriptPath
        $record = $existing.Replay.Scripts | Where-Object Path -eq $relative
        if (-not $record) { throw "Evidence replay entry missing: $relative" }
        $record.SHA256 = Get-Hash $scriptPath
        $record.Body = [IO.File]::ReadAllText($scriptPath)
    }
    $json = ConvertTo-Json -InputObject $existing -Depth 70
    if ($json -match '(?i)[A-Z]:\\Users\\|[A-Z]:/Users/') { throw 'Evidence contains a user-specific absolute path.' }
