    $savedText = ($json -replace "`r?`n", "`r`n") + "`r`n"
    [IO.File]::WriteAllBytes($output, $utf8.GetPreamble() + $utf8.GetBytes($savedText))
    $updated = Read-Json $output
    if ($updated.Change.CandidateSourceDiff -notmatch '\[\.\. elements\]' -or $updated.Change.CharacterizationTestsFullSource.Length -eq 0 -or $updated.FormalExploration.Summary.Experiment -ne '2026-10-19-json-array-bulk') { throw 'Evidence source/test retention or experiment label verification failed.' }
    Write-Output ([ordered]@{Path=Get-RelativePath $output;SHA256=Get-Hash $output;SummarySHA256=Get-Hash $summaryPath;Experiment=$updated.FormalExploration.Summary.Experiment;GeometricMeanRatio=$updated.FormalExploration.Summary.PairedGeometricMeanRatio;Confidence95=$updated.FormalExploration.Summary.Confidence95;SourceDiffRetained=($updated.Change.CandidateSourceDiff.Length -gt 0);TestSourceRetained=($updated.Change.CharacterizationTestsFullSource.Length -gt 0)} | ConvertTo-Json -Depth 4 -Compress)
    exit 0
}

function Get-RunRecord([int]$Block, [string]$Variant) {
    $name = '{0:d2}-{1}' -f $Block, $Variant
    $directory = Join-Path $root "runs/exploration/$name"
    $summaryPath = Join-Path $directory 'run-summary.json'
    $summary = Read-Json $summaryPath
    if ($summary.Run -ne $name -or $summary.Batch -ne 'exploration' -or $summary.Variant -ne $Variant -or $summary.ExitCode -ne 0 -or $summary.ActualCount -ne 8 -or $summary.ResultCount -ne 8 -or $summary.WarmupCount -ne 16) { throw "Run identity/status mismatch: $name" }
    if ($summary.InputBytes -ne 4172062 -or $summary.InputSHA256 -ne $inputHash -or $summary.LibraryDLLSHA256 -ne $libraryHash -or $summary.Affinity -ne 4 -or $summary.TieredPGO -ne 1) { throw "Input, library, or job mismatch: $name" }
    if (@($summary.ActualIterations).Count -ne 8 -or @($summary.ResultIterations).Count -ne 8 -or @($summary.ActualIterations + $summary.ResultIterations | Where-Object Operations -ne 4).Count -ne 0) { throw "Iteration/invocation mismatch: $name" }
    $hostLog = Join-Path $directory $summary.HostLog
    $stderrLog = Join-Path $directory $summary.Stderr
    if (-not (Test-Path -LiteralPath $hostLog) -or (Get-Item -LiteralPath $stderrLog).Length -ne 0) { throw "Run logs missing or stderr not empty: $name" }
    if ([IO.File]::ReadAllText($hostLog) -notmatch '(?m)^// AfterAll\s*$') { throw "Completion marker missing: $name" }
    [ordered]@{
        Name=$name
        SummaryPath=Get-RelativePath $summaryPath
        SummarySHA256=Get-Hash $summaryPath
        Summary=$summary
        HostLogPath=Get-RelativePath $hostLog
        HostLogSHA256=Get-Hash $hostLog
        StderrPath=Get-RelativePath $stderrLog
        StderrSHA256=Get-Hash $stderrLog
    }
}

